<?php
// Path: public/manage/club-finance.php
// 機能: クラブ申請から振込先・入金・訂正・年度承認を一画面で確認。受付保留と本人・職務権限をサーバーで検査する。
declare(strict_types=1);
require_once __DIR__.'/_bootstrap.php';
use Jmrc\Auth\HttpFailure;
use Jmrc\Club\ClubOperations;
$auth=jmrc_auth();$user=$auth->requireIdentity();$db=jmrc_db();$config=jmrc_auth_config();$service=new ClubOperations($db,$config);
$caps=$service->capabilities($user['id']);$json=($_GET['format']??'')==='json';$record=null;$error=null;$intake=0;
$number=static function(array $in,string $key,int $default=0):int{if(!isset($in[$key])){return $default;}$n=filter_var($in[$key],FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>1000000000]]);if($n===false){throw new HttpFailure(422,'対象・年度を確認してください');}return $n;};
$text=static function(array $in,string $key,string $default=''):string{$v=$in[$key]??$default;if(!is_string($v)){throw new HttpFailure(422,'入力の形式を確認してください');}return $v;};
$messages=['issue'=>'クラブ会費の請求を確認しました。','confirm'=>'入金確認を記録しました。','reverse'=>'元の充当を取り消して資格を再判定しました。','reallocate'=>'同じ請求へ再充当しました。','approve'=>'年度登録を承認しました。'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    $auth->verifyCsrf($_POST['_csrf']??null);$intake=$number($_POST,'intake');$action=$text($_POST,'action');
    try{
        $record=$service->execute($user['id'],$intake,$action,$_POST);
        if($json){header('Content-Type: application/json; charset=utf-8');echo json_encode($record,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
        header('Location: /manage/club-finance.php?intake='.$intake.'&done='.$action,true,303);exit;
    }catch(HttpFailure $ex){
        if(!in_array($ex->status,[409,422,503],true)){throw $ex;}http_response_code($ex->status);
        if($json){header('Content-Type: application/json; charset=utf-8');echo json_encode(['error'=>$ex->getMessage()],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
        $error=$ex->getMessage();$record=$service->read($user['id'],$intake);
    }
}elseif($_SERVER['REQUEST_METHOD']!=='GET'){throw new HttpFailure(405,'POST required');}
else{$intake=$number($_GET,'intake');if($intake){$record=$service->read($user['id'],$intake);}}
$year=($_GET['year']??'')===''?0:$number($_GET,'year');$filter=$text($_GET,'state','all');$list=$service->listing($user['id'],$year,$filter);$enabled=\Jmrc\Club\ClubIntakePolicy::enabled($config);
$done=$text($_GET,'done');
if($json){header('Content-Type: application/json; charset=utf-8');echo json_encode(['record'=>$record,'registrations'=>$list,'capabilities'=>$caps,'enabled'=>$enabled],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$value=static fn(string $key,string $fallback='')=>is_string($_POST[$key]??null)?$_POST[$key]:$fallback;
$jst=static fn($at)=>$at?(new DateTimeImmutable($at,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Tokyo'))->format('Y/m/d H:i'):'未記録';
$hidden=static function(string $action)use($auth,$e,$intake,$value):void{echo '<input type="hidden" name="_csrf" value="'.$e($auth->csrfToken()).'"><input type="hidden" name="intake" value="'.$e($intake).'"><input type="hidden" name="action" value="'.$e($action).'">';if(in_array($action,['confirm','reverse','reallocate'],true)){$key=($_POST['action']??'')===$action?$value('operation',bin2hex(random_bytes(24))):bin2hex(random_bytes(24));echo '<input type="hidden" name="operation" value="'.$e($key).'">';}};
$labels=['uninvoiced'=>'請求前','unpaid'=>'入金待ち・不足・再確認','approval'=>'入金済み・年度承認待ち','ready'=>'年度登録済み','inactive'=>'差し戻し・不承認'];
require_once __DIR__.'/_office-layout.php';header('Content-Type: text/html; charset=utf-8');jmrc_office_header('クラブ会費・承認','クラブ登録');
?>
<p class="office-intro">事務局が申請内容を照合した後の、請求・振込・入金確認・年度承認を確認できます。</p>
<?php if(!$enabled):?><p class="portal-notice" role="status">クラブ会費・年度承認は準備中です。受付と書込みは停止しています。画面と手順だけ確認できます。</p><?php endif;?>
<?php if($error):?><section class="office-panel" role="alert" tabindex="-1"><h2>入力・設定を確認してください</h2><p><?=$e($error)?></p><p>下の入力内容と現在の状況を確認してください。請求IDを手入力して別のクラブへ操作する方式ではありません。</p></section><?php endif;?>
<?php if(isset($messages[$done])):?><p class="office-success" role="status"><?=$e($messages[$done])?></p><?php endif;?>
<nav class="office-actions" aria-label="クラブ登録の確認先"><a class="office-button secondary" href="/manage/club-register.php<?=$caps['approve']?'?all=1':''?>">申請内容・照合・差し戻し</a><?php if($caps['accounts']):?><a class="office-button secondary" href="/manage/bank-settings.php">入金先口座の設定</a><?php endif;?></nav>
<section class="office-panel" aria-labelledby="steps"><h2 id="steps">手続きの順番</h2><ol><li>本人がクラブ登録を申請します。</li><li>事務局がJAF番号・区分・既存クラブを照合します。</li><li>正式な振込先の設定後、年会費と入会金の請求を発行します。</li><li>案内された口座へ振り込み、事務局・財務が銀行明細を確認して入金を記録します。</li><li>満額入金後に事務局が年度登録を承認します。</li></ol><p>年度開始前の「年度登録済み」と、年度内の「資格有効」は別に表示します。未入金・不足・未承認では有効になりません。</p></section>
<?php if($record):$r=$record['intake'];$invoice=$record['invoice'];$state=$record['eligibility'];$on=$enabled&&in_array($r['source_mode'],['shadow','portal'],true);?>
<section class="office-panel" aria-labelledby="target"><h2 id="target"><?=$e($r['year'].'年度 '.$r['name_short'])?></h2><p><?=$e($r['name_full'])?> ／ クラブコード <?=$e($r['display_code'])?> ／ 申請番号 <?=$e($r['id'])?></p><p><strong><?=$e($labels[$record['stage']])?></strong></p><dl class="office-definition office-amounts"><dt>年会費</dt><dd><?=number_format((int)$r['annual_yen'])?> 円</dd><dt>入会金</dt><dd><?=number_format((int)$r['joining_yen'])?> 円</dd><dt>請求合計</dt><dd><?=number_format((int)$r['annual_yen']+(int)$r['joining_yen'])?> 円</dd><dt>確認済み充当額</dt><dd data-amount="paid"><?=number_format((int)($invoice['paid_yen']??0))?> 円</dd><dt>残額</dt><dd data-amount="balance"><?=number_format((int)($invoice['balance_yen']??((int)$r['annual_yen']+(int)$r['joining_yen'])))?> 円</dd><dt>年度承認</dt><dd data-state="approved"><?=$state['approved']?'承認済み':'未承認'?></dd><dt>年度開始前の登録</dt><dd data-state="ready"><?=$state['ready']?'年度登録済み':'条件未完了'?></dd><dt>現在の資格</dt><dd data-state="active"><?=$state['active']?'有効':'現在は無効'?></dd></dl>
<?php if(!$invoice):?><p>正式な振込先が未設定・確認待ちの場合は発行できません。仮の口座や料金で請求しません。</p><form method="post" action="/manage/club-finance.php" aria-label="クラブ会費の請求"><?php $hidden('issue');?><button class="office-button" type="submit" <?=$on?'':'disabled'?>>請求と振込案内を発行する</button></form><?php else:?><p>請求番号 <?=$e($invoice['invoice_no'])?>。再発行操作で請求を重複作成しません。</p><?php endif;?></section>
<?php if($invoice):?><section class="office-panel" aria-labelledby="guide"><h2 id="guide">請求発行時の振込先</h2><?php if($record['guide']['ready']):?><p class="office-readonly" data-guide="details"><?=nl2br($e($record['guide']['details']))?></p><p>振込人名義の末尾に、申請者のエントラントID <strong><?=$e($r['applicant_user_id'])?></strong> を付けてください。</p><p>振込先は請求時の記録です。クラブ会費にペイメントコアは使いません。既に振込済みの場合は、入金状況を確認してから対応してください。</p><?php else:?><p class="portal-notice"><?=$e($record['guide']['notice'])?></p><?php endif;?></section>
<?php if($caps['confirm']):?><section class="office-panel" aria-labelledby="confirm"><h2 id="confirm">銀行明細を確認して入金を記録</h2><p>銀行明細の実際の入金日・金額・取引番号を入力します。重複する取引番号は登録できません。不足額は残額として残し、過入金は未充当として保持します。</p><form method="post" action="/manage/club-finance.php" class="office-form" aria-label="クラブ入金確認"><?php $hidden('confirm');?><div class="office-field"><label for="received-on">実際の入金日</label><input id="received-on" name="received_on" type="date" required value="<?=$e($value('received_on'))?>"></div><div class="office-field"><label for="confirm-amount">入金額（円）</label><input id="confirm-amount" name="amount" inputmode="numeric" pattern="[0-9]+" required maxlength="10" value="<?=$e($value('amount'))?>"></div><div class="office-field office-wide"><label for="reference">銀行の取引番号</label><input id="reference" name="reference" maxlength="100" required value="<?=$e($value('reference'))?>"><p class="office-help">銀行明細の取引を識別する番号です。振込人名義の末尾IDとは異なります。</p></div><div class="office-submit"><button class="office-button" type="submit" <?=$on&&$record['guide']['ready']&&(int)$invoice['balance_yen']>0?'':'disabled'?>>銀行明細と照合して記録する</button></div></form></section><?php endif;?>
<section class="office-panel" aria-labelledby="payments"><h2 id="payments">入金と訂正の明細</h2><?php if(!$record['payments']):?><p>入金記録はまだありません。</p><?php endif;?><ul class="office-records"><?php foreach($record['payments'] as $p):?><li><h3>入金ID <?=$e($p['id'])?></h3><dl class="office-definition"><dt>実際の入金日（日本時間）</dt><dd><?=$e(substr($jst($p['received_at']),0,10))?></dd><dt>取引番号</dt><dd><?=$e($p['source_key'])?></dd><dt>金額</dt><dd><?=number_format((int)$p['amount_yen'])?> 円</dd><dt>未充当額</dt><dd><?=number_format((int)$p['unallocated_yen'])?> 円</dd></dl></li><?php endforeach;foreach($record['allocations'] as $a):?><li><h3>充当ID <?=$e($a['id'])?></h3><p><?=number_format((int)$a['amount_yen'])?> 円 ／ 入金ID <?=$e($a['payment_id'])?> ／ <?=$e($jst($a['created_at']))?></p><?php if($a['reverses_id']!==null):?><p>訂正対象 <?=$e($a['reverses_id'])?> ／ 理由 <?=$e($a['reason'])?></p><?php endif;?></li><?php endforeach;?></ul></section>
<?php if($caps['correct']):?><section class="office-panel" aria-labelledby="correction"><h2 id="correction">入金の充当を訂正</h2><p>元の明細と訂正理由を残して充当を取り消します。実際の返金や別の請求・口座への振替は行いません。訂正するとクラブと個人の資格も再判定します。</p><form method="post" action="/manage/club-finance.php" class="office-form" aria-label="クラブ充当の訂正"><?php $hidden('reverse');?><div class="office-field"><label for="allocation">取り消す元の充当</label><select id="allocation" name="allocation" required><option value="">明細を選択</option><?php foreach($record['allocations'] as $a):if((int)$a['amount_yen']<=0||in_array($a['id'],array_column($record['allocations'],'reverses_id'))){continue;}?><option value="<?=$e($a['id'])?>">充当<?=$e($a['id'])?>：<?=number_format((int)$a['amount_yen'])?>円</option><?php endforeach;?></select></div><div class="office-field office-wide"><label for="reason">訂正理由</label><textarea id="reason" name="reason" maxlength="500" required><?=$e($value('reason'))?></textarea></div><div class="office-submit"><button class="office-button secondary" type="submit" <?=$on?'':'disabled'?>>元の充当を取り消す</button></div></form>
<h3>同じ請求への再充当</h3><form method="post" action="/manage/club-finance.php" class="office-form" aria-label="クラブ会費の再充当"><?php $hidden('reallocate');?><div class="office-field"><label for="payment">元の入金</label><select id="payment" name="payment" required><option value="">未充当額がある入金を選択</option><?php foreach($record['payments'] as $p):if($p['unallocated_yen']<=0){continue;}?><option value="<?=$e($p['id'])?>">入金<?=$e($p['id'])?>：未充当<?=number_format($p['unallocated_yen'])?>円</option><?php endforeach;?></select></div><div class="office-field"><label for="reallocate-amount">再充当額（円）</label><input id="reallocate-amount" name="amount" inputmode="numeric" pattern="[0-9]+" maxlength="10" required></div><div class="office-submit"><button class="office-button secondary" type="submit" <?=$on?'':'disabled'?>>同じ請求へ再充当する</button></div></form></section><?php endif;?>
<?php if($caps['approve']):?><section class="office-panel" aria-labelledby="approve"><h2 id="approve">年度登録の承認</h2><p>申請内容の照合と満額入金を確認してください。年度開始前は登録済みとし、個人会員の資格・正本は切り替えません。</p><form method="post" action="/manage/club-finance.php" aria-label="クラブ年度承認"><?php $hidden('approve');?><p><label><input type="checkbox" name="checked" value="1" required>申請内容と銀行明細による満額入金を確認しました</label></p><button class="office-button" type="submit" <?=$on&&$state['paid']&&in_array($r['status'],['pending','approved'],true)?'':'disabled'?>>年度登録を承認する</button></form></section><?php endif;?>
<?php endif;?>
<section class="office-panel" aria-labelledby="history"><h2 id="history">操作履歴</h2><ul class="office-list"><?php foreach($record['history'] as $h):?><li><?=$e($jst($h['occurred_at']))?> ／ <?=$e(['CLUB_INVOICED'=>'請求発行','CLUB_PAYMENT_CONFIRMED'=>'入金確認','CLUB_PAYMENT_REVERSED'=>'充当訂正','CLUB_PAYMENT_REALLOCATED'=>'再充当','CLUB_APPROVED'=>'年度承認','CLUB_CONTACT_UPDATED'=>'連絡先訂正'][$h['action']]??$h['action'])?> ／ 担当者ID <?=$e($h['actor_user_id'])?></li><?php endforeach;?></ul><p>履歴は直近30件です。操作ログの保存期間は既定の3か月です。</p></section>
<?php endif;?>
<section class="office-panel" aria-labelledby="list"><h2 id="list"><?=$caps['staff']?'事務局・財務のクラブ一覧':'自分が申請したクラブ'?></h2><form method="get" action="/manage/club-finance.php" class="office-form" aria-label="クラブ一覧の絞込み"><div class="office-field"><label for="year">年度</label><select id="year" name="year"><option value="">すべての年度</option><?php foreach($db->query('SELECT year FROM portal_years ORDER BY year DESC')->fetchAll(PDO::FETCH_COLUMN) as $y):?><option value="<?=$e($y)?>" <?=(int)$y===$year?'selected':''?>><?=$e($y)?>年度</option><?php endforeach;?></select></div><div class="office-field"><label for="state">状況</label><select id="state" name="state"><?php foreach(ClubOperations::FILTERS as $key=>$label):?><option value="<?=$e($key)?>" <?=$key===$filter?'selected':''?>><?=$e($label)?></option><?php endforeach;?></select></div><div class="office-submit"><button class="office-button secondary" type="submit">一覧を絞り込む</button></div></form><p>指定年度の直近100件から表示します。事務局の照合が完了した申請が対象です。</p><?php if(!$list):?><p>該当するクラブはありません。提出前・照合待ちの内容は「申請内容・照合・差し戻し」から確認してください。</p><?php endif;?><ul class="office-list"><?php foreach($list as $item):?><li><a href="/manage/club-finance.php?intake=<?=$e($item['intake']['id'])?>"><?=$e($item['intake']['year'].' '.$item['intake']['name_short'].' ／ '.$labels[$item['stage']])?></a></li><?php endforeach;?></ul></section>
<?php jmrc_office_footer(); ?>
